<?php
session_start();
require_once __DIR__.'/config/db.php';
require_once __DIR__ . '/config/helpers.php';
if(empty($_SESSION['sems_csrf']))$_SESSION['sems_csrf']=bin2hex(random_bytes(32));
if(!isset($_SESSION['user'])||!in_array(($_SESSION['user']['role']??''),['Student','Teacher','Principal','Admin'],true)){header('Location: login.php');exit;}
$eventID=(int)($_GET['eventID']??0);
$role=$_SESSION['user']['role'];$myRegSql=$role==='Student'?'(SELECT r.status FROM registrations r JOIN students s ON s.studentID=r.studentID WHERE s.userID=? AND r.eventID=e.eventID LIMIT 1)':'NULL';$statusFilter=$role==='Student'?" AND e.status='Approved'":'';$sql="SELECT e.*,owner.userID AS ownerID,owner.name AS ownerName,owner.email AS ownerEmail,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status NOT IN ('Rejected','Cancelled')) AS totalRegistered,$myRegSql AS myRegistration FROM events e LEFT JOIN users owner ON owner.userID=e.createdBy WHERE e.eventID=?$statusFilter";$q=$pdo->prepare($sql);$q->execute($role==='Student'?[(int)$_SESSION['user']['userID'],$eventID]:[$eventID]);$event=$q->fetch();if(!$event){http_response_code(404);exit('Event not found.');}
$feedbackQ=$pdo->prepare('SELECT f.feedbackID,f.userID,f.rating,f.comments,f.photoPath,f.submittedAt,u.name FROM feedback f JOIN users u ON u.userID=f.userID WHERE f.eventID=? ORDER BY f.submittedAt DESC');$feedbackQ->execute([$eventID]);$feedback=$feedbackQ->fetchAll();
$tasks=[];if(in_array($role,['Teacher','Principal'],true)){$taskQ=$pdo->prepare("SELECT u.name,t.taskTitle,t.taskDescription FROM event_tasks t JOIN users u ON u.userID=t.assignedTo WHERE t.eventID=? AND t.taskStatus<>'Cancelled' ORDER BY u.name");$taskQ->execute([$eventID]);$tasks=$taskQ->fetchAll();}$timestamp=strtotime($event['eventDate'].' '.$event['eventTime']);$finish=strtotime($event['eventDate'].' '.($event['eventEndTime']?:$event['eventTime']));$category=$timestamp>time()?'Upcoming':(time()<=$finish?'Ongoing':'Past');$deadline=$event['registrationDeadline']?strtotime($event['registrationDeadline']):$timestamp;$canRegister=$role==='Student'&&$category==='Upcoming'&&$deadline>time()&&(int)$event['totalRegistered']<(int)$event['capacity']&&!$event['myRegistration'];$name=$_SESSION['user']['name'];$pq=$pdo->prepare('SELECT profilePhoto FROM users WHERE userID=?');$pq->execute([(int)$_SESSION['user']['userID']]);$photo=$pq->fetchColumn();$returnPage=$role==='Student'?'dashboard.php':($role==='Teacher'?'teacher_events.php':'admin_dashboard.php');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=school_h($event['eventName'])?> | SchoolSphere</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/teacher.css?v=5"><link rel="stylesheet" href="assets/portal.css?v=12"><link rel="stylesheet" href="assets/ui-polish.css?v=28"><script src="assets/proof-viewer.js?v=3" defer></script><?php if($role!=='Teacher'):?><script src="assets/confirm-actions.js?v=1" defer></script><?php endif;?><link rel="stylesheet" href="assets/school-sphere.css?v=18"></head><body class="<?= $role==='Teacher'?'teacher-dashboard':'portal-body' ?>"><?php if($role==='Teacher'): ?><div class="teacher-layout"><?php require __DIR__.'/teacher_nav.php'; ?><main class="teacher-main"><header class="teacher-topbar"><div><span class="teacher-eyebrow">EVENT DETAILS · <?=school_h(strtoupper($category))?></span><h1><?=school_h($event['eventName'])?></h1></div><div class="teacher-account"><span class="teacher-avatar"><?=school_h(strtoupper(substr($name,0,1)))?></span><strong><?=school_h($name)?></strong></div></header><div class="teacher-content"><?php else: ?><aside class="portal-sidebar"><a class="portal-brand" href="<?=$returnPage?>">SEMS <small><?=school_h(strtoupper($role))?> PORTAL</small></a><nav><?php if($role==='Student')$eventNav=['dashboard'=>'Dashboard','events'=>'Events','my_registrations'=>'My Registrations','calendar'=>'Calendar','my_payments'=>'My Payments','attendance'=>'Attendance','financial_assistance'=>'Financial Assistance','profile'=>'Profile'];elseif($role==='Teacher')$eventNav=['teacher_dashboard'=>'Dashboard','teacher_events'=>'My Events','teacher_registrations'=>'Registrations','teacher_attendance'=>'Attendance','teacher_reports'=>'Reports','calendar'=>'Calendar'];else $eventNav=['admin_dashboard'=>'Dashboard','admin_users'=>'Users','admin_events'=>'Events','admin_registrations'=>'Registrations','admin_reports'=>'Reports'];foreach($eventNav as $href=>$label):?><a class="<?=str_contains($href,'events')?'active':''?>" href="<?=$href?>.php"><?=school_h($label)?></a><?php endforeach;?></nav><a class="portal-logout" href="logout.php">Log Out</a></aside><main class="portal-main"><header class="portal-header"><div><small>EVENT DETAILS · <?=school_h(strtoupper($category))?></small><h1><?=school_h($event['eventName'])?></h1></div><div class="portal-account"><a class="portal-inbox" href="inbox.php">Inbox</a><a class="portal-profile-link" href="profile.php"><?php if($photo):?><img class="portal-avatar" src="<?=school_h($photo)?>" alt=""><?php else:?><span class="portal-avatar portal-avatar-fallback"><?=school_h(strtoupper(substr($name,0,1)))?></span><?php endif;?><span class="portal-account-identity"><strong><?=school_h($name)?></strong><small><?=school_h($role)?></small></span></a></div></header><div class="portal-content"><?php endif; ?><a class="portal-back-link" href="<?=$returnPage?>">← Back</a><section class="event-detail-hero"><div><?php $detailBanner=$event['eventPoster']?:(((int)$eventID%2)?'assets/sems-school-open-day.jpg':'assets/sems-school-activities.jpg');?><img src="<?=school_h($detailBanner)?>" alt="<?=school_h($event['eventName'])?> banner"><span class="event-oversight-status"><?=school_h($category)?></span><h2><?=school_h($event['eventName'])?></h2><p><?=nl2br(school_h($event['description']?:'No event description provided.'))?></p></div><aside><small>EVENT HANDLER</small><strong><?=school_h($event['ownerName']??'School')?></strong><span><?php if($publicId=school_public_person_id($pdo,(int)($event['ownerID']??0))):?><?=school_h($publicId)?> · <?php endif;?><?=school_h($event['ownerEmail']??'—')?></span></aside></section><section class="portal-card"><h2>Event information</h2><div class="event-detail-facts"><p><small>Date and time</small><strong><?=school_h(date('d M Y',strtotime($event['eventDate'])).' · '.date('h:i A',strtotime($event['eventTime'])).'–'.date('h:i A',strtotime($event['eventEndTime']?:$event['eventTime'])))?></strong></p><p><small>Location</small><strong><?=school_h($event['location'])?></strong></p><p><small>Registration closes</small><strong><?=school_h($event['registrationDeadline']?date('d M Y, h:i A',strtotime($event['registrationDeadline'])):'At event start')?></strong></p><p><small>Places</small><strong><?= (int)$event['totalRegistered']?> / <?= (int)$event['capacity']?></strong></p><p><small>Fee</small><strong>RM <?=number_format((float)$event['fee'],2)?></strong></p><?php if($role==='Student'):?><p><small>My registration</small><strong><?=school_h($event['myRegistration']?:'Not registered')?></strong></p><?php endif;?></div><?php if($canRegister):?><form method="post" action="events.php" class="event-register-action"><input type="hidden" name="csrf" value="<?=school_h($_SESSION['sems_csrf'])?>"><button class="small-button" name="register_event" value="<?=(int)$event['eventID']?>">Register for event</button></form><?php elseif($event['myRegistration']):?><p>Your registration status: <strong><?=school_h($event['myRegistration'])?></strong>. Manage it under <a href="my_registrations.php">My Registrations</a>.</p><?php elseif($category==='Past'):?><p>Registration is closed because this event has passed.</p><?php endif;?></section><?php if(in_array($role,['Teacher','Principal'],true)):?><section class="portal-card"><h2>Event team</h2><div class="event-detail-people"><article><span>Event organiser</span><h3><?=school_h($event['ownerName']??'School')?></h3><small><?php if($publicId=school_public_person_id($pdo,(int)($event['ownerID']??0))):?><?=school_h($publicId)?> · <?php endif;?><?=school_h($event['ownerEmail']??'—')?></small></article><?php foreach($tasks as $task):?><article><span>Committee teacher</span><h3><?=school_h($task['name'])?></h3><p><strong><?=school_h($task['taskTitle'])?></strong><br><?=school_h($task['taskDescription']?:'')?></p></article><?php endforeach;?></div></section><?php endif;?><section class="portal-card"><h2>Student feedback <span class="event-section-count"><?=count($feedback)?></span></h2><p>Feedback shared by students who attended this event.</p><div class="event-feedback-grid"><?php if(!$feedback):?><p>No feedback has been shared for this event yet.</p><?php endif;?><?php foreach($feedback as $item):?><article><header><strong><?=school_h($item['name'])?> · <?= (int)$item['rating']?>/5</strong><small><?=school_h(date('d M Y',strtotime($item['submittedAt'])))?></small></header><p><?=nl2br(school_h($item['comments']))?></p><?php if($item['photoPath']):?><a class="feedback-photo-open" data-proof-viewer data-proof-type="image" data-proof-title="Feedback photo" href="<?=school_h($item['photoPath'])?>"><span>View photo</span></a><?php endif;?><?php if($role==='Student'&&(int)$item['userID']===(int)$_SESSION['user']['userID']):?><a class="feedback-edit-action" href="feedback.php?edit=<?=(int)$item['feedbackID']?>#feedback-form">Edit or delete my feedback</a><?php endif;?></article><?php endforeach;?></div><?php if($category==='Past'&&$role==='Student'):?><p class="event-feedback-invite">Have feedback to share? <a class="portal-link" href="feedback.php?eventID=<?=(int)$eventID?>">Write feedback for this event</a></p><?php endif;?></section></div></main><?php if($role==='Teacher'): ?></div><?php endif; ?></body></html>













